def map_stages(df):
    STAGE_OUTCOME = {
        "Proposal": "Open",
        "Prospecting": "Open", 
        "Negotiation": "Open",
        "Closed Lost": "Lost",
        "Closed - Won": "Won"
    }
    df["Outcome"] = [STAGE_OUTCOME.get(s, s) for s in df["Stage"]]
    return df

def win_rates(df):
    rates = {}
    for rep in sorted(df["Owner"].unique()):
        mine = df[df["Owner"] == rep]
        # Add condition to filter only rows with valid outcomes
        valid = mine[mine["Outcome"].isin(["won", "lost"])]
        won = int((valid["Outcome"] == "won").sum())
        lost = int((valid["Outcome"] == "lost").sum())
        if (won + lost) > 0:
            rates[rep] = round(won / (won + lost), 4)
    return rates

